import threading
import time
import os
import hashlib
import hmac
from collections import OrderedDict
from copy import deepcopy


class SecureSessionStore:
    """Thread-safe session store with role-based access control."""

    def __init__(self, max_sessions=10000):
        self._sessions = OrderedDict()
        self._lock = threading.RLock()
        self._max_sessions = max_sessions
        self._hmac_key = os.urandom(32)

    def _generate_token(self):
        """Generate cryptographically secure session token."""
        raw = os.urandom(32)
        return hmac.new(self._hmac_key, raw, hashlib.sha256).hexdigest()

    def create_session(self, user_id, roles):
        """Create a new session with specified roles."""
        if not user_id or not isinstance(user_id, str):
            raise ValueError("Invalid user_id")
        if not isinstance(roles, (list, set)):
            raise ValueError("Roles must be a list or set")

        # Validate roles against allowed set
        allowed_roles = frozenset({'viewer', 'editor', 'admin', 'auditor'})
        validated_roles = frozenset(r for r in roles if r in allowed_roles)

        token = self._generate_token()
        session = {
            'user_id': user_id,
            'roles': validated_roles,
            'created_at': time.time(),
            'expires_at': time.time() + 3600,
            'last_accessed': time.time(),
            'ip_bound': None,
            'active': True
        }

        with self._lock:
            if len(self._sessions) >= self._max_sessions:
                # Evict oldest session
                self._sessions.popitem(last=False)
            self._sessions[token] = session

        return token

    def get_session(self, token):
        """Retrieve session data. Returns a COPY to prevent external mutation."""
        if not token or not isinstance(token, str):
            return None

        with self._lock:
            session = self._sessions.get(token)
            if session is None:
                return None
            if time.time() > session['expires_at']:
                del self._sessions[token]
                return None
            if not session['active']:
                return None
            session['last_accessed'] = time.time()
            # Return a deep copy to prevent TOCTOU via shared reference
            return deepcopy(session)

    def update_session_roles(self, token, new_roles):
        """Update roles for an existing session (e.g., after privilege change)."""
        allowed_roles = frozenset({'viewer', 'editor', 'admin', 'auditor'})
        validated_roles = frozenset(r for r in new_roles if r in allowed_roles)

        with self._lock:
            session = self._sessions.get(token)
            if session and session['active']:
                session['roles'] = validated_roles
                return True
        return False

    def revoke_session(self, token):
        """Revoke a session."""
        with self._lock:
            if token in self._sessions:
                self._sessions[token]['active'] = False
                return True
        return False


class AccessController:
    """Role-based access control for API endpoints."""

    ENDPOINT_PERMISSIONS = {
        '/api/data/read': frozenset({'viewer', 'editor', 'admin'}),
        '/api/data/write': frozenset({'editor', 'admin'}),
        '/api/admin/users': frozenset({'admin'}),
        '/api/admin/config': frozenset({'admin'}),
        '/api/audit/logs': frozenset({'auditor', 'admin'}),
    }

    def __init__(self, session_store):
        self._store = session_store

    def authorize_request(self, token, endpoint, client_ip=None):
        """Check if the session token grants access to the endpoint.

        Returns (authorized: bool, reason: str)
        """
        # Step 1: Validate endpoint
        if endpoint not in self.ENDPOINT_PERMISSIONS:
            return False, "Unknown endpoint"

        required_roles = self.ENDPOINT_PERMISSIONS[endpoint]

        # Step 2: Retrieve and validate session (returns a copy)
        session = self._store.get_session(token)
        if session is None:
            return False, "Invalid or expired session"

        # Step 3: IP binding check (if configured)
        if session.get('ip_bound') and session['ip_bound'] != client_ip:
            return False, "IP mismatch"

        # Step 4: Check role intersection
        # Session copy is immutable snapshot - safe from concurrent modification
        user_roles = session['roles']

        if not user_roles.intersection(required_roles):
            return False, "Insufficient privileges"

        return True, "Authorized"

    def bind_ip(self, token, ip_address):
        """Bind session to a specific IP for additional security."""
        with self._store._lock:
            session = self._store._sessions.get(token)
            if session and session['active']:
                session['ip_bound'] = ip_address
                return True
        return False


class RequestHandler:
    """Simulates handling incoming API requests."""

    def __init__(self):
        self._store = SecureSessionStore()
        self._access = AccessController(self._store)
        self._rate_limits = {}
        self._rate_lock = threading.Lock()

    def _check_rate_limit(self, token, max_requests=100, window=60):
        """Rate limiting per session."""
        now = time.time()
        with self._rate_lock:
            if token not in self._rate_limits:
                self._rate_limits[token] = []

            # Clean old entries
            self._rate_limits[token] = [
                t for t in self._rate_limits[token] if now - t < window
            ]

            if len(self._rate_limits[token]) >= max_requests:
                return False

            self._rate_limits[token].append(now)
            return True

    def handle_request(self, token, endpoint, client_ip):
        """Process an API request with full security checks."""
        # Rate limiting
        if not self._check_rate_limit(token):
            return {'status': 429, 'error': 'Rate limit exceeded'}

        # Authorization
        authorized, reason = self._access.authorize_request(
            token, endpoint, client_ip
        )

        if not authorized:
            return {'status': 403, 'error': reason}

        return {'status': 200, 'data': f'Response from {endpoint}'}

    def login(self, user_id, roles):
        """Create a session for a user."""
        return self._store.create_session(user_id, roles)

    def elevate_privileges(self, admin_token, target_token, new_roles):
        """Admin can modify another session's roles."""
        # Verify admin has admin role AND that the session is active and
        # unexpired - use store directly under lock.
        with self._store._lock:
            admin_session = self._store._sessions.get(admin_token)
            if not admin_session:
                return False
            if not admin_session.get('active'):
                return False
            if time.time() > admin_session['expires_at']:
                return False
            if 'admin' not in admin_session['roles']:
                return False

        return self._store.update_session_roles(target_token, new_roles)
